head.script:
// 화면 리사이징

// 영문공시 번역지원 개발(유가)(20200904)
// SrM-000214854 개선사항 반영(20201204)
// SrM-000247674 코스닥 영문번역서비스 개발(20230224)
// 현업이 직접 수정할수 있도록 함 (20220527)
// SrM-000249428 코스닥 법인 직접 입력, 코스닥 이메일 기능 추가(20230421)

scwin.gAcptNo;
scwin.gIsurCd;
scwin.gRdoMktId;
scwin.gLdMktTp = js_market;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        scwin.setCode();
        await scwin.checkCond();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF19000.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_FromCal_onclick
 * @description img_FromCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FromCal_onclick = function() {
    try {
        popUpCalendar2(edt_FromDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF19000.img_FromCal_onclick" });
    }
};

/**
 * @method
 * @name img_ToCal_onclick
 * @description img_ToCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ToCal_onclick = function() {
    try {
        popUpCalendar2(edt_ToDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF19000.img_ToCal_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_FromDate, edt_ToDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF19000.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.checkCond();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF19000.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_DsclList_OnLoadError
 * @description dts_DsclList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_DsclList.errorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF19000.dts_DsclList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_DsclList_OnLoadCompleted
 * @description dts_DsclList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DsclList_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF19000.dts_DsclList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        if (scwin.gLdMktTp === "1") {
            $c.data.downloadGridViewExcel(grd_Grid, {fileName: "번역지원목록", type: "8"});
        } else {
            $c.data.downloadGridViewExcel(grd_Grid, {fileName: "번역지원목록", type: "2"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF19000.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        scwin.setContnId(row);
        if (colid === "DOC_TITLE") {
            await $c.stf.openDisclViewer(scwin.gAcptNo, "R");
        } else if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF19000.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_form_add_onclick
 * @description 「서식추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_form_add_onclick = async function() {
    try {
        // 서식추가
        scwin.setMktId();
        await scwin.formAdd();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF19000.btn_form_add_onclick" });
    }
};

/**
 * @method
 * @name btn_isur_add_onclick
 * @description 「회사추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_isur_add_onclick = async function() {
    try {
        // 회사추가
        scwin.setMktId();
        await scwin.IsurcdAdd();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF19000.btn_isur_add_onclick" });
    }
};

/**
 * @method
 * @name btn_email_onclick
 * @description 「메일발송」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_email_onclick = function() {
    try {
        // 메일발송
        scwin.setMktId();
        scwin.sendMail();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF19000.btn_email_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&FROM_DATE=" + edt_FromDate.getValue(); // 일자별
    url += "&TO_DATE=" + edt_ToDate.getValue(); // 일자별
    url += "&LD_MKT_TP=" + rdo_MKT_ID.getValue(); // 시장구분
    url += "&SCREN_ID=" + 'ULDSTF19000.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_DsclList",
        action : "/DsclSearchAll.do",
        ref : "",
        target : "dts_DsclList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description 기간 from~ to  셋팅
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    //  기간 from~ to  셋팅
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue(vCurDate); // 현재날짜
    edt_ToDate.setValue(vCurDate); // 현재날짜

    // 현업이 직접 수정할수 있도록 함 20220527
    btn_isur_add.show("");
    btn_form_add.show("");
    btn_email.show("");
    if (scwin.gLdMktTp === "1") {
        rdo_MKT_ID.setValue(scwin.gLdMktTp);
        panel_mkt.hide();
        btn_email.hide();
    } else if (scwin.gLdMktTp === "2") {
        rdo_MKT_ID.setValue(scwin.gLdMktTp);
        panel_mkt.hide();
        $c.cm.setColumnProp(grd_Grid, 'CHRG1', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'CHRG_NM1', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'EMAIL1', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'CELLPHONE_NO1', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'CHRG3', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'CHRG_NM3', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'EMAIL3', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'CELLPHONE_NO3', 'Show', 'true');
    } else {
        rdo_MKT_ID.setValue("1");
        panel_mkt.show("");
        $c.cm.setColumnProp(grd_Grid, 'CHRG1', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'CHRG_NM1', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'EMAIL1', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'CELLPHONE_NO1', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'CHRG3', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'CHRG_NM3', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'EMAIL3', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'CELLPHONE_NO3', 'Show', 'true');
    }
};

/**
 * @method
 * @name checkCond
 * @description 일자 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkCond = async function() {
    // 일자 체크
    if (edt_FromDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }
    await scwin.search();
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclList.getCellData(Number(obj), "ACPT_NO");
    scwin.gIsurCd = dts_DsclList.getCellData(Number(obj), "ISUR_CD");
};

/**
 * @method
 * @name setMktId
 * @description 시장구분
 * @returns {void}
 * @hidden N
 */
scwin.setMktId = function() {
    scwin.gRdoMktId = rdo_MKT_ID.getValue();
};

/**
 * @method
 * @name IsurcdAdd
 * @description Isurcd Add 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.IsurcdAdd = async function() {
    const options = {
        id: "ULDSFT19000_POP",
        title: "영문번역대상법인 추가",
        type: "pageFramePopup",
        width: "490px",
        height: "570px"
    };

    const data = {
        // TO-DO : 팝업으로 전달할 파라미터 설정
    };

    const result = await $c.win.openPopup("/dsclsrch/ULDSFT19000_POP.gfm", options, data);
    // TO-DO : result 값 확인 후 업무 로직 추가
};

/**
 * @method
 * @name formAdd
 * @description form Add 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.formAdd = async function() {
    const options = {
        id: "ULDSFT19000_FORM",
        title: "영문번역대상서식 추가",
        type: "pageFramePopup",
        width: "490px",
        height: "570px"
    };

    const data = {
        // TO-DO : 팝업으로 전달할 파라미터 설정
    };

    const result = await $c.win.openPopup("/dsclsrch/ULDSFT19000_FORM.gfm", options, data);
    // TO-DO : result 값 확인 후 업무 로직 추가
};

/**
 * @method
 * @name sendMail
 * @description 메일발송
 * @returns {void}
 * @hidden N
 */
scwin.sendMail = function() {
    let url = "";
    url = "/dsclsrch/ULDSTF19000_EMAIL.gfm?";
    url += "frameID=" + frame.FrameID;
    $c.frame.path("../../").GWinOpen("ULDSFT19000", url, "이메일 발송", 200, 10, 700, 660, "");

    // frame.CreateDialogFrame("virWinMail",  "/dsclsrch/ULDSFT19000_EMAIL.gfm" , "이메일 발송", js_com_left, js_com_top, 800, 760, "tool");

};
